"""Typed SQLite persistence boundary for the reading list."""

import sqlite3
from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path

from flask import current_app, g


@dataclass(frozen=True)
class Book:
    """A book record returned by the persistence interface."""

    id: int
    title: str
    author: str
    created_at: str | None = None
    is_read: bool = False


class BookStore:
    """Store books in SQLite while keeping SQL private to this module."""

    def __init__(
        self,
        database_path: str,
        connect: Callable[[], sqlite3.Connection] | None = None,
    ) -> None:
        self.database_path = database_path
        self._connect_provider = connect

    def _connect(self) -> sqlite3.Connection:
        if self._connect_provider is not None:
            return self._connect_provider()
        if self.database_path != ":memory:":
            Path(self.database_path).parent.mkdir(parents=True, exist_ok=True)
        connection = sqlite3.connect(self.database_path)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA journal_mode = WAL")
        connection.execute("PRAGMA foreign_keys = ON")
        return connection

    def initialize(self) -> None:
        """Create or migrate the books table without changing existing rows."""
        connection = self._connect()
        try:
            connection.execute(
                """
                CREATE TABLE IF NOT EXISTS books (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL,
                    author TEXT NOT NULL,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    is_read INTEGER NOT NULL DEFAULT 0
                )
                """
            )
            columns = {
                row["name"]
                for row in connection.execute("PRAGMA table_info(books)").fetchall()
            }
            if "is_read" not in columns:
                connection.execute(
                    "ALTER TABLE books ADD COLUMN is_read INTEGER NOT NULL DEFAULT 0"
                )
            connection.commit()
        finally:
            if self._connect_provider is None:
                connection.close()

    def add(self, title: str, author: str) -> Book:
        """Persist and return one book, rejecting incomplete submissions."""
        if not isinstance(title, str) or not title.strip():
            raise ValueError("title is required")
        if not isinstance(author, str) or not author.strip():
            raise ValueError("author is required")

        connection = self._connect()
        try:
            cursor = connection.execute(
                "INSERT INTO books (title, author) VALUES (?, ?)",
                (title, author),
            )
            connection.commit()
            row = connection.execute(
                "SELECT id, title, author, created_at, is_read FROM books WHERE id = ?",
                (cursor.lastrowid,),
            ).fetchone()
            assert row is not None
            return _book_from_row(row)
        finally:
            if self._connect_provider is None:
                connection.close()

    def list_ordered(self) -> list[Book]:
        """Return books in their SQLite-assigned insertion order."""
        connection = self._connect()
        try:
            rows = connection.execute(
                "SELECT id, title, author, created_at, is_read FROM books ORDER BY id"
            ).fetchall()
            return [_book_from_row(row) for row in rows]
        finally:
            if self._connect_provider is None:
                connection.close()

    def mark_read(self, book_id: int) -> bool:
        """Mark one book as read and report whether it exists."""
        connection = self._connect()
        try:
            cursor = connection.execute(
                "UPDATE books SET is_read = 1 WHERE id = ?", (book_id,)
            )
            connection.commit()
            return cursor.rowcount == 1
        finally:
            if self._connect_provider is None:
                connection.close()

    def remove(self, book_id: int) -> bool:
        """Delete a book and report whether a row was removed."""
        connection = self._connect()
        try:
            cursor = connection.execute("DELETE FROM books WHERE id = ?", (book_id,))
            connection.commit()
            return cursor.rowcount == 1
        finally:
            if self._connect_provider is None:
                connection.close()


def _book_from_row(row: sqlite3.Row) -> Book:
    return Book(
        id=row["id"],
        title=row["title"],
        author=row["author"],
        created_at=row["created_at"],
        is_read=bool(row["is_read"]),
    )


def _context_connection() -> sqlite3.Connection:
    connection = g.get("reading_list_db")
    if connection is None:
        database_path = current_app.config["DATABASE"]
        if database_path != ":memory:":
            Path(database_path).parent.mkdir(parents=True, exist_ok=True)
        connection = sqlite3.connect(database_path)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA journal_mode = WAL")
        connection.execute("PRAGMA foreign_keys = ON")
        g.reading_list_db = connection
    return connection


def get_book_store() -> BookStore:
    """Return the store bound to the current Flask application context."""
    store = g.get("reading_list_store")
    if store is None:
        store = BookStore(current_app.config["DATABASE"], _context_connection)
        g.reading_list_store = store
    return store


def close_connection(_: object | None = None) -> None:
    """Close the current request/workflow connection, if one was opened."""
    connection = g.pop("reading_list_db", None)
    if connection is not None:
        connection.close()


def initialize(database_path: str) -> None:
    """Initialize the schema without exposing SQLite to application code."""
    BookStore(database_path).initialize()
"""HTTP routes for the ReadingList application."""

from flask import Blueprint, jsonify, redirect, render_template, request, url_for

from app.persistence import BookStore, get_book_store

bp = Blueprint("reading_list", __name__)


def _store() -> BookStore:
    return get_book_store()


@bp.get("/")
def index():
    return render_template("index.html", books=_store().list_ordered(), error=None)


@bp.post("/books")
def add_book():
    """Add a book, returning to the list or showing the invalid fields."""
    title = request.form.get("title", "")
    author = request.form.get("author", "")
    missing = [
        field
        for field, value in (("title", title), ("author", author))
        if not value.strip()
    ]
    if missing:
        fields = " and ".join(missing)
        message = f"Please provide a {fields}."
        return (
            render_template(
                "index.html", books=_store().list_ordered(), error=message
            ),
            400,
        )

    _store().add(title, author)
    return redirect(url_for("reading_list.index"))


@bp.post("/books/<int:book_id>/remove")
def remove_book(book_id: int):
    """Remove one book identified by its stable database id."""
    _store().remove(book_id)
    return redirect(url_for("reading_list.index"))


@bp.post("/books/<int:book_id>/mark-read")
@bp.post("/books/<int:book_id>/read")
def mark_read(book_id: int):
    """Mark one book as read and return to the reading list."""
    _store().mark_read(book_id)
    return redirect(url_for("reading_list.index"))


@bp.get("/health")
def health():
    _store().list_ordered()
    return jsonify(status="ok")
"""Flask application factory for ReadingList."""

import tempfile
from collections.abc import Mapping
from pathlib import Path
from typing import Any

from flask import Flask

from config import Config


def create_app(overrides: Mapping[str, Any] | Config | None = None) -> Flask:
    """Create an isolated ReadingList application instance."""
    settings = Config.load(require_secret=overrides is None)
    app = Flask(__name__, instance_relative_config=True)
    app.config.from_mapping(
        SECRET_KEY=settings.secret_key,
        DATABASE=settings.database_path,
    )
    if isinstance(overrides, Config):
        app.config.update(
            SECRET_KEY=overrides.secret_key,
            DATABASE=overrides.database_path,
        )
    elif overrides is not None:
        app.config.update(overrides)

    if (
        isinstance(overrides, Mapping)
        and overrides.get("TESTING") is True
        and "DATABASE" not in overrides
    ):
        app.config["DATABASE"] = ":memory:"

    if app.config["DATABASE"] == ":memory:":
        temporary_database = tempfile.NamedTemporaryFile(
            prefix="reading-list-", suffix=".db", delete=False
        )
        temporary_database.close()
        app.config["DATABASE"] = temporary_database.name
    else:
        database_path = Path(app.config["DATABASE"])
        database_path.parent.mkdir(parents=True, exist_ok=True)

    from app.persistence import close_connection, initialize
    from app.routes import bp

    initialize(app.config["DATABASE"])
    app.teardown_appcontext(close_connection)
    app.register_blueprint(bp)
    return app
